import '../datasources/firebase_auth_data_source.dart';
import '../models/auth_user.dart';
abstract interface class AuthGateway { Future<AuthUser> login({required String email,required String password}); Future<AuthUser> register(Map<String,dynamic> data); Future<AuthUser?> restoreSession(); Future<void> logout(); }
class FirebaseAuthRepository implements AuthGateway { FirebaseAuthRepository(this._source); final FirebaseAuthDataSource _source; @override Future<AuthUser> login({required String email,required String password})=>_source.login(email,password); @override Future<AuthUser> register(Map<String,dynamic> data)=>_source.register(data); @override Future<AuthUser?> restoreSession()=>_source.restore(); @override Future<void> logout()=>_source.logout(); Future<void> forgotPassword(String email)=>_source.forgot(email); Future<void> resendVerification()=>_source.verifyEmail(); Future<void> resetPassword(Map<String,dynamic> data) => Future.error(UnsupportedError('Firebase reset links are handled by Firebase email action links.')); }
